//! Opening book: positions (by `State::hash`) to candidate actions with weights.
//!
//! The book is `data/book_theory.txt`, compiled into the binary (so the browser build has it
//! too) and parsed on first use. It is generated by `ktools bookgen` from the annotated 5dpgn
//! lines of `data/book_theory_src.txt` (see that file for the tags):
//!
//! ```text
//! # comment
//! P <G line>                       a book position: "G <promotions> <5duci position> moves ..."
//! m <play|know> <weight> <lan> ; <5dpgn>   a candidate action from the last P position
//! N <name>                         the opening's name at the last P position
//! ```
//!
//! `play` actions are what the engine plays from the position (weighted random choice);
//! `know` actions are known theory it never plays itself (blunders, dubious moves, the losing
//! side's moves in a trap), kept so that the positions after them, and the replies there, are
//! in the book.

use crate::core::action::Action;
use crate::core::perft::parse_g_line;
use crate::core::state::State;
use std::collections::HashMap;
use std::sync::OnceLock;

/// One candidate action of a book position.
#[derive(Clone, Debug)]
pub struct BookMove {
    pub action: Action,
    /// The action's LAN tokens (as in a 5DUCI move list).
    pub lan: String,
    /// The action in 5dpgn (short notation), for display.
    pub pgn: String,
    /// The engine may play it (otherwise it is only known theory).
    pub play: bool,
    /// Relative weight among the position's `play` actions.
    pub weight: u32,
}

#[derive(Default, Debug)]
pub struct Book {
    positions: HashMap<u64, Vec<BookMove>>,
    /// Opening names (`N` lines): "Family: Variation: Line", by the position they are reached at.
    names: HashMap<u64, String>,
}

impl Book {
    /// Parse a book file. Every action is checked legal in its position.
    pub fn parse(text: &str) -> Result<Book, String> {
        let mut book = Book::default();
        let mut cur: Option<(u64, State)> = None;
        for (n, line) in text.lines().enumerate() {
            let line = line.trim();
            let err = |e: String| format!("book line {}: {}", n + 1, e);
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            if let Some(g) = line.strip_prefix("P ") {
                let s = parse_g_line(g).map_err(err)?;
                let h = s.hash();
                book.positions.entry(h).or_default();
                cur = Some((h, s));
            } else if let Some(name) = line.strip_prefix("N ") {
                let (h, _) = cur.as_ref().ok_or_else(|| err("name before any position".into()))?;
                if book.names.insert(*h, name.trim().to_string()).is_some() {
                    return Err(err("two names for one position".into()));
                }
            } else if let Some(m) = line.strip_prefix("m ") {
                let (h, s) = cur.as_ref().ok_or_else(|| err("move before any position".into()))?;
                let (head, pgn) = m.split_once(';').unwrap_or((m, ""));
                let mut it = head.split_whitespace();
                let play = match it.next() {
                    Some("play") => true,
                    Some("know") => false,
                    k => return Err(err(format!("bad tag {:?}", k))),
                };
                let weight: u32 = it.next().and_then(|w| w.parse().ok()).ok_or_else(|| err("bad weight".into()))?;
                let lan = it.collect::<Vec<_>>().join(" ");
                let moves = crate::web::tree::parse_lan_moves(&lan).map_err(err)?;
                if moves.is_empty() {
                    return Err(err("empty action".into()));
                }
                crate::web::tree::play_action(s, &moves).map_err(|e| err(format!("illegal action {}: {}", lan, e)))?;
                let action = Action::from_vector(&moves, s);
                book.positions.get_mut(h).unwrap().push(BookMove { action, lan, pgn: pgn.trim().to_string(), play, weight });
            } else {
                return Err(err(format!("unknown line {:?}", line)));
            }
        }
        Ok(book)
    }

    /// The book the engine uses (`data/book_theory.txt`); empty if it does not parse (a test
    /// makes sure it does).
    pub fn theory() -> &'static Book {
        static BOOK: OnceLock<Book> = OnceLock::new();
        BOOK.get_or_init(|| Book::parse(include_str!("../../data/book_theory.txt")).unwrap_or_default())
    }

    /// Number of positions and of candidate actions.
    pub fn size(&self) -> (usize, usize) {
        (self.positions.len(), self.positions.values().map(|v| v.len()).sum())
    }

    /// The opening's name at `s` ("Family: Variation: Line"), if the position carries one. A
    /// game's opening is the last name found along it.
    pub fn opening_name(&self, s: &State) -> Option<&str> {
        self.names.get(&s.hash()).map(|n| n.as_str())
    }

    /// Number of named positions.
    pub fn name_count(&self) -> usize {
        self.names.len()
    }

    /// All book actions (play and know) of `s`, if it is a book position.
    pub fn probe(&self, s: &State) -> Option<&[BookMove]> {
        self.positions.get(&s.hash()).map(|v| v.as_slice()).filter(|v| !v.is_empty())
    }

    /// A `play` action of `s`, chosen with probability proportional to its weight using
    /// `seed`; `None` when `s` has none.
    pub fn choose(&self, s: &State, seed: u64) -> Option<&BookMove> {
        let moves = self.probe(s)?;
        let total: u64 = moves.iter().filter(|m| m.play).map(|m| m.weight as u64).sum();
        if total == 0 {
            return None;
        }
        let mut r = mix(seed ^ s.hash()) % total;
        for m in moves.iter().filter(|m| m.play) {
            if r < m.weight as u64 {
                return Some(m);
            }
            r -= m.weight as u64;
        }
        None
    }

    /// Total `play` weight of `s` (0 if none), for reporting.
    pub fn play_weight(&self, s: &State) -> u32 {
        self.probe(s).map_or(0, |v| v.iter().filter(|m| m.play).map(|m| m.weight).sum())
    }
}

/// A random seed (from the standard library's per-process random keys).
pub fn random_seed() -> u64 {
    use std::hash::{BuildHasher, Hasher};
    static COUNTER: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    let mut h = std::collections::hash_map::RandomState::new().build_hasher();
    h.write_u64(COUNTER.fetch_add(1, std::sync::atomic::Ordering::Relaxed));
    h.finish()
}

fn mix(mut x: u64) -> u64 {
    x ^= x >> 33;
    x = x.wrapping_mul(0xff51afd7ed558ccd);
    x ^= x >> 33;
    x = x.wrapping_mul(0xc4ceb9fe1a85ec53);
    x ^ (x >> 33)
}

// ------------------------------------------------------------------ generation

/// One tagged (or untagged) action of a source line.
struct SrcMove {
    play: Option<bool>,
    weight: u32,
}

/// A source action's `{name ...}` tag.
type SrcName = Option<String>;

/// Build the book file from the annotated 5dpgn source (`data/book_theory_src.txt`): one game
/// per non-comment line, actions tagged `{play N}` or `{know}` (untagged actions take the tag
/// given to the same action elsewhere). Positions are written in order of first appearance,
/// each with its actions, preceded by the source comment block of the line that first reached
/// it.
pub fn generate(src: &str) -> Result<String, String> {
    use crate::core::variants::state_from_setup;
    use crate::web::pgn::{action_to_pgn_short, parse_5dpgn};
    use crate::web::record::setup_to_uci;
    use crate::web::tree::action_lan;

    struct Pos {
        g: String,
        note: Vec<String>,
        moves: Vec<(String, String, SrcMove, usize)>,
        name: Option<String>,
    }
    let mut order: Vec<u64> = Vec::new();
    let mut pos: HashMap<u64, Pos> = HashMap::new();
    let mut note: Vec<String> = Vec::new();
    for (n, line) in src.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() {
            note.clear();
            continue;
        }
        if let Some(c) = line.strip_prefix('#') {
            note.push(c.trim().to_string());
            continue;
        }
        let err = |e: String| format!("source line {}: {}", n + 1, e);
        let game = parse_5dpgn(line, None).map_err(err)?;
        let mut s = state_from_setup(&game.setup).map_err(err)?;
        let mut g = format!("G {} {} moves", game.setup.promotions.0, setup_to_uci(&game.setup));
        let mut node = &game.root;
        let mut pending_note = std::mem::take(&mut note);
        while let Some(child) = node.children.first() {
            let act = child.action.as_ref().ok_or_else(|| err("action missing".into()))?;
            let mut tag = SrcMove { play: None, weight: 0 };
            let mut name: SrcName = None;
            for c in &child.comments {
                let mut w = c.split_whitespace();
                match w.next() {
                    Some("name") => {
                        let n = c.trim().strip_prefix("name").unwrap_or("").trim().to_string();
                        if n.is_empty() {
                            return Err(err(format!("empty {{name}} after {}", child.text)));
                        }
                        name = Some(n);
                    }
                    Some("play") => {
                        tag.play = Some(true);
                        tag.weight = w.next().and_then(|x| x.parse().ok()).ok_or_else(|| err(format!("bad weight in {{{}}} after {}", c, child.text)))?;
                    }
                    Some("know") => tag.play = Some(false),
                    _ => return Err(err(format!("unknown tag {{{}}} after {}", c, child.text))),
                }
            }
            let lan = action_lan(&s, act);
            let next = crate::web::tree::play_action(&s, act.moves()).map_err(|e| err(format!("{}: {}", child.text, e)))?;
            let h = s.hash();
            let p = pos.entry(h).or_insert_with(|| {
                order.push(h);
                Pos { g: g.clone(), note: std::mem::take(&mut pending_note), moves: Vec::new(), name: None }
            });
            match p.moves.iter_mut().find(|m| m.0 == lan) {
                Some(m) => {
                    if let Some(play) = tag.play {
                        if let Some(old) = m.2.play {
                            if old != play || old && m.2.weight != tag.weight {
                                return Err(err(format!("conflicting tags for {}", child.text)));
                            }
                        }
                        m.2 = tag;
                    }
                }
                None => p.moves.push((lan.clone(), action_to_pgn_short(&s, act), tag, n + 1)),
            }
            for m in act.moves() {
                g += &format!(" {}", m);
            }
            g += " submit";
            if let Some(n) = name {
                // The name belongs to the position after the action.
                let after = next.hash();
                let p = pos.entry(after).or_insert_with(|| {
                    order.push(after);
                    Pos { g: g.clone(), note: Vec::new(), moves: Vec::new(), name: None }
                });
                match &p.name {
                    Some(old) if *old != n => return Err(err(format!("two names for one position: {:?} and {:?}", old, n))),
                    _ => p.name = Some(n),
                }
            }
            s = next;
            node = child;
        }
    }
    let mut out = String::from(
        "# Kairos opening book, generated by `ktools bookgen data/book_theory_src.txt` from the annotated\n\
         # 5dpgn lines there (sources and tags explained in that file); do not edit by hand.\n\
         # P <G line>: a book position; m <play|know> <weight> <action LAN> ; <5dpgn>: its actions.\n",
    );
    for h in order {
        let p = &pos[&h];
        if !p.note.is_empty() {
            out.push('\n');
            for l in &p.note {
                out += &format!("# {}\n", l);
            }
        }
        out += &format!("P {}\n", p.g);
        if let Some(n) = &p.name {
            out += &format!("N {}\n", n);
        }
        for (lan, pgn, tag, line) in &p.moves {
            let Some(play) = tag.play else {
                return Err(format!("source line {}: action {} is tagged nowhere", line, pgn));
            };
            out += &format!("m {} {} {} ; {}\n", if play { "play" } else { "know" }, if play { tag.weight } else { 0 }, lan, pgn);
        }
    }
    Ok(out)
}
